<?php
session_start();
require_once __DIR__ . '/../lead-engine/config.php';
if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/');exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function money($n){return '$'.number_format((float)$n,0);}
function sb145d($m,$ep,$p=null){
  $ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));
  curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$m,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json','Prefer: return=representation'],CURLOPT_TIMEOUT=>25]);
  if($p!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($p));
  $b=curl_exec($ch);curl_close($ch);$d=json_decode($b,true);return is_array($d)?$d:[];
}
$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  $id=$_POST['id']??''; $stage=$_POST['stage']??'';
  if($id && in_array($stage,['call','enrich','nurture','review','ignore','archived'],true)){
    sb145d('PATCH','seller_acquisition_director?id=eq.'.rawurlencode($id),['acquisition_stage'=>$stage,'status'=>$stage==='archived'?'archived':'active','updated_at'=>date('c')]);
    $msg='Acquisition item updated.';
  }
}
$rows=sb145d('GET','seller_acquisition_director?select=*&status=eq.active&order=mark_priority.desc,acquisition_score.desc,created_at.desc&limit=400');
$briefs=sb145d('GET','seller_acquisition_briefings?select=*&order=created_at.desc&limit=5');
$brief=$briefs[0]??[];
$stats=['total'=>count($rows),'ready'=>0,'enrich'=>0,'review'=>0,'mark'=>0,'luxury'=>0,'commission'=>0];
foreach($rows as $r){if(!empty($r['ready_to_contact']))$stats['ready']++;if(!empty($r['needs_enrichment']))$stats['enrich']++;if(!empty($r['needs_review']))$stats['review']++;if(!empty($r['mark_priority']))$stats['mark']++;if((int)($r['luxury_score']??0)>=90)$stats['luxury']++;$stats['commission']+=(float)($r['estimated_commission']??0);}
$cronKey=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'YOUR_KEY';
