<section class="grid"><div class="kpi"><div class="n"><?=h($stats['total'])?></div>Total</div><div class="kpi"><div class="n"><?=h($stats['ready'])?></div>Ready</div><div class="kpi"><div class="n"><?=h($stats['enrich'])?></div>Enrich</div><div class="kpi"><div class="n"><?=h($stats['review'])?></div>Review</div><div class="kpi"><div class="n"><?=h($stats['mark'])?></div>Mark</div><div class="kpi"><div class="n"><?=h($stats['luxury'])?></div>Luxury</div><div class="kpi"><div class="n"><?=money($stats['commission'])?></div>2.5%</div></section>
<div class="layout"><section class="panel"><h2>Top Seller Opportunities</h2><table><tr><th>Score</th><th>Opportunity</th><th>Source</th><th>Value</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><div class="score"><?=h($r['acquisition_score'])?></div><div class="muted"><?=h($r['acquisition_stage'])?></div></td><td><strong><?=h($r['address']?:$r['name'])?></strong> <?php if(!empty($r['mark_priority'])):?><span class="mark">MARK</span><?php endif;?><div class="muted"><?=h($r['town'])?><br><?=h($r['phone'])?> <?=h($r['email'])?></div></td><td><?=h($r['source_type'])?><div class="muted">DNC: <?=h($r['dnc_status'])?><br>Realtor: <?=h($r['realtor_status'])?></div></td><td><?=money($r['estimated_sale_price'])?><div class="muted">Commission <?=money($r['estimated_commission'])?><br>Expected <?=money($r['expected_value'])?></div></td><td><?=h($r['recommended_action'])?><div class="muted"><?=h($r['recommended_script'])?></div><form method="post"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn" name="stage" value="call">Call</button><button class="btn light" name="stage" value="enrich">Enrich</button><button class="btn light" name="stage" value="review">Review</button><button class="btn light" name="stage" value="nurture">Nurture</button><button class="btn light" name="stage" value="archived">Archive</button></form></td></tr><?php endforeach;?></table></section><section class="panel"><h2>Jessica Acquisition Brief</h2><div style="padding:16px"><pre><?=h($brief['briefing_text']??'Build Seller Director to create briefing.')?></pre></div></section></div>
